// migratedSources are the source prefixes (a directory ending in "/" or a file
// path, relative to internal/) of each migrated view. They are scanned for the
// retired mechanisms (criterion 2a/2b, and the hard-coded glyphs of 3). A prefix may be a file so a view
// that migrates in two steps (OCI A-09a/A-09a2/A-09b, explorer A-10a/b) can be scanned
// file by file.
var migratedSources = map[command.ViewType][]string{
	command.ViewJobs:       {"ui/jobsview/"},
	command.ViewWorkspaces: {"ui/workspaces/"},
	command.ViewSecurity:   {"ui/security/"},
	// OCI migrates in steps (A-09a images, A-09a2 registry browser, A-09b the rest):
	// only the files that belong to the migrated tables are scanned. Excluded:
	// commands.go (the refresh tea.Tick). The registry browser (A-09a2) is in.
	command.ViewOCIResources: {
		"ui/oci_resources/activity.go", "ui/oci_resources/table.go", "ui/oci_resources/jobs.go",
		"ui/oci_resources/images.go", "ui/oci_resources/results.go", "ui/oci_resources/view.go",
		"ui/oci_resources/model.go", "ui/oci_resources/busy.go", "ui/oci_resources/registries.go",
		"ui/oci_resources/update.go", "ui/oci_resources/keys.go",
		"ui/oci_resources/registry_browser.go", "ui/oci_resources/browser_keys.go",
		"ui/oci_resources/browser_view.go", "ui/oci_resources/browser_state.go",
		"ui/oci_resources/browser_bridge.go", "ui/oci_resources/browser_tags.go",
	},
	// The explorer is fully migrated (A-10a the tree, A-10b the clone list):
	// the whole package is scanned.
	command.ViewGitExplorer: {"ui/forge/explorer/"},
	command.ViewTemplates:   {"ui/templates/"},
	// Netdiag is migrated except forward_model.go, whose ticker is a data
	// refresh, and ports_commands.go (portsTickCmd is the data refresh tick, not
// groupedModel is the variant with members.
func browsingModel(t *testing.T) Model {
	t.Helper()
	m := feed(t, loadedModel(t), testutil.Key(keymap.Browser))
	if m.registryBrowser == nil {
		t.Fatal("'b' did not open the registry browser")
	}
	return m
}

// searchedModel returns a browser showing tags from both registries.
func searchedModel(t *testing.T) Model {
	t.Helper()
	return feed(t, browsingModel(t),
		MultiRegistryTagsLoadedMsg{
			EntryKey: "prod", RegistryURL: "registry.example.com", Alias: "prod", Repo: "api",
			Tags: []string{"v1", "v2"},
		},
		MultiRegistryTagsLoadedMsg{
			EntryKey: "hub", RegistryURL: "docker.io", Alias: "hub", Repo: "api",
			Tags: []string{"latest"},
		},
	)
}

// ── Opening ──────────────────────────────────────────────────────────────────

// The browser needs somewhere to search, so it says what is missing rather than
// opening empty.
func TestBrowserNeedsARegistry(t *testing.T) {
	cfg := testConfig()
		t.Errorf("the results came from %v, want both registries", seen)
	}
}

// A slow registry keeps the browser in its searching state, so the list does
// not look complete while it is still filling.
func TestTheBrowserSearchesUntilEveryRegistryAnswers(t *testing.T) {
	m := browsingModel(t)
	m.registryBrowser.pendingSearches = 2 // two registries queried

	m = feed(t, m, MultiRegistryTagsLoadedMsg{
		EntryKey: "prod", RegistryURL: "registry.example.com", Repo: "api", Tags: []string{"v1"},
	})
	if !m.registryBrowser.IsSearching() {
		t.Error("the browser stopped searching with one registry outstanding")
	}

	m = feed(t, m, MultiRegistryTagsLoadedMsg{EntryKey: "hub", RegistryURL: "docker.io", Repo: "api", Tags: []string{"latest"}})
	if m.registryBrowser.IsSearching() {
		t.Error("the browser is still searching once every registry answered")
	}
}

// A duplicate or late response used to drive the counter negative, so the next
// search started from that base and its spinner never showed.
func TestExtraResponsesDoNotDriveTheCounterNegative(t *testing.T) {
	m := browsingModel(t)
	m.registryBrowser.pendingSearches = 1

	m = feed(t, m,
		MultiRegistryTagsLoadedMsg{EntryKey: "prod", RegistryURL: "registry.example.com", Repo: "api", Tags: []string{"v1"}},
		MultiRegistryTagsLoadedMsg{EntryKey: "prod", RegistryURL: "registry.example.com", Repo: "api", Tags: []string{"v1"}},
		MultiRegistryTagsLoadedMsg{EntryKey: "prod", RegistryURL: "registry.example.com", Repo: "api", Tags: []string{"v1"}},
	)

	if got := m.registryBrowser.pendingSearches; got != 0 {
		t.Errorf("pendingSearches = %d after three responses to one search, want 0", got)
	}

	// A fresh search must be reported as in flight.
	m.registryBrowser.pendingSearches = 1
	if !m.registryBrowser.IsSearching() {
		t.Error("IsSearching() is false for a search that has just started")
	}
}

// One registry failing must not lose the other's results.
func TestAFailedSearchKeepsTheOtherResults(t *testing.T) {
	m := feed(t, browsingModel(t),
		MultiRegistryTagsLoadedMsg{EntryKey: "prod", RegistryURL: "registry.example.com", Repo: "api", Tags: []string{"v1", "v2"}},
		MultiRegistryTagsLoadedMsg{EntryKey: "hub", RegistryURL: "docker.io", Repo: "api", Err: errors.New("401 unauthorized")},
	)

	if got := len(m.registryBrowser.tags); got != 2 {
		t.Errorf("tags = %d, want the registry that answered to still be listed", got)
	}
}

// Last-updated times arrive separately, after the tag list, so the table is
// usable before the enrichment lands.
func TestTagMetadataEnrichesTheRows(t *testing.T) {
	m := searchedModel(t)

	m = feed(t, m, MultiRegistryTagsMetaMsg{
		EntryKey: "prod", RegistryURL: "registry.example.com",
		Repo: "api",
		Meta: map[string]time.Time{"v1": at(1)},
	})

	var enriched bool
	for _, tag := range m.registryBrowser.tags {
		t.Errorf("the query is %q after confirming, want it kept", b.filterInput.Value())
	}
	if !b.FilterIsVisible() {
		t.Error("a confirmed query left the filter bar hidden")
	}
}

// A tag typed in the filter also matches the repository, since one search can
// span repositories on different registries.
func TestTheTagFilterAlsoMatchesTheRepository(t *testing.T) {
	m := resultsModel(t,
		MultiRegistryTagsLoadedMsg{EntryKey: "prod", RegistryURL: "registry.example.com", Alias: "prod", Repo: "api", Tags: []string{"v1"}},
		MultiRegistryTagsLoadedMsg{EntryKey: "hub", RegistryURL: "docker.io", Alias: "hub", Repo: "web", Tags: []string{"v1"}},
	)
	b := m.registryBrowser

	m = feed(t, m, testutil.Key("/"))
		t.Errorf("rows = %d for %d entries, want one extra for the header", len(b.rows), len(b.entries))
	}
}

// ── The result filter's group level (§3.8 step 6) ────────────────────────────

// `r` gains a group stop: narrowing to everything from one Nexus is one
// keystroke rather than one per proxy.
func TestTheResultFilterHasAGroupLevel(t *testing.T) {
	m := groupedModel(t)
	m = typeInto(t, m, "api")
	m = feed(t, m, testutil.Key("enter"))
	m = feed(t, m, stampGen(m,
		MultiRegistryTagsLoadedMsg{EntryKey: memberKey("prod", "registry.example.com", "docker-hosted"), RegistryURL: "registry.example.com", Alias: "prod/docker-hosted", Repo: "docker-hosted/api", Tags: []string{"v1"}},
		MultiRegistryTagsLoadedMsg{EntryKey: memberKey("prod", "registry.example.com", "dhi-proxy"), RegistryURL: "registry.example.com", Alias: "prod/dhi", Repo: "dhi-proxy/api", Tags: []string{"v2"}},
		MultiRegistryTagsLoadedMsg{EntryKey: "hub", RegistryURL: "docker.io", Alias: "hub", Repo: "api", Tags: []string{"latest"}},
	)...)
	b := m.registryBrowser

	m = feed(t, m, testutil.Key("r"))
	if b.registryFilter.groupSlug != "prod" {
		t.Fatalf("the first stop is %+v, want the group", b.registryFilter)
	}
	if got := len(b.tagTable.Visible()); got != 2 {
		t.Errorf("%d rows under the group filter, want both its members'", got)
	}

func TestEndOfALoadStopsTheBlink(t *testing.T) {
	ends := []struct {
		name  string
		model func(*testing.T) Model
		msgs  []interface{}
	}{
		{"images", tabLoading(0), []interface{}{ImagesListMsg{}, ImagesListMsg{Err: errors.New("down")}}},
		{"networks", tabLoading(1), []interface{}{NetworksListMsg{}, NetworksListMsg{Err: errors.New("down")}}},
		{"volumes", tabLoading(2), []interface{}{VolumesListMsg{}, VolumesListMsg{Err: errors.New("down")}}},
		{"tag search", searching, []interface{}{MultiRegistryTagsLoadedMsg{EntryKey: "prod", RegistryURL: "registry.example.com", Repo: "api", Tags: []string{"v1"}}}},
		{"inspection", inspecting, []interface{}{
			NetworkInspectLoadedMsg{NetworkID: "net11111", NetworkName: "bridge"},
			NetworkInspectLoadedMsg{NetworkID: "net11111", Err: errors.New("down")},
		}},
	}
	for _, e := range ends {
		for i, msg := range e.msgs {
			t.Run(e.name, func(t *testing.T) {
				m := e.model(t)
				if !m.WantsBlink() {
					t.Fatalf("fixture %d: not blinking before the end", i)
				}
				m = feed(t, m, stampGen(m, msg)...)
				if m.WantsBlink() {
					t.Error("still asks for the blink after the load ended")
				}
				if got := plainOciInfoLine(m, 200); strings.ContainsAny(got, "●○") || strings.Contains(got, "Searching") || strings.Contains(got, "Loading") {
					t.Errorf("the footer still shows the load: %q", got)
				}
			})

